static const Entry** s_sorted;
static int s_n;

static int by_english(const void* a, const void* b)
{
	return strcmp((*(const Entry* const*)a)->en, (*(const Entry* const*)b)->en);
}

const char* tr(const char* english)
{
	int lang = ev_language();
	if (!english || lang < 2 || lang > 5)
		return english;
	if (!s_sorted) {
		s_n = (int)(sizeof TABLE / sizeof *TABLE);
		s_sorted = malloc((size_t)s_n * sizeof *s_sorted);
		if (!s_sorted) {
			s_n = 0;
			return english;
		}
		for (int i = 0; i < s_n; i++)
			s_sorted[i] = &TABLE[i];
		qsort(s_sorted, (size_t)s_n, sizeof *s_sorted, by_english);
	}
	int lo = 0, hi = s_n - 1;
	while (lo <= hi) {
		int mid = (lo + hi) / 2, c = strcmp(english, s_sorted[mid]->en);
		if (!c) {
			const char* t = s_sorted[mid]->t[lang - 2];
			return t && *t ? t : english;
		}
		if (c < 0)
			hi = mid - 1;
		else
			lo = mid + 1;
	}
	return english;
}
